+document.addEventListener('DOMContentLoaded', () => {
+    const form = document.getElementById('contactForm');
+    const fullNameInput = document.getElementById('fullName');
+    const emailInput = document.getElementById('email');
+    const phoneInput = document.getElementById('phone');
+
+    const validators = {
+        fullName: (val) => {
+            if (!val.trim()) return 'Full name is required.';
+            return '';
+        },
+        email: (val) => {
+            if (!val.trim()) return 'Email address is required.';
+            const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+            if (!emailRegex.test(val)) return 'Please enter a valid email address.';
+            return '';
+        },
+        phone: (val) => {
+            if (!val.trim()) return ''; // Optional
+            const phoneRegex = /^\d{3}-\d{3}-\d{4}$/;
+            if (!phoneRegex.test(val)) return 'Please use the format: 123-456-7890';
+            return '';
+        }
+    };
+
+    const validateField = (input, validator) => {
+        const errorDiv = document.getElementById(`${input.id}Error`);
+        const errorMessage = validator(input.value);
+        
+        if (errorMessage) {
+            input.classList.add('invalid');
+            input.setAttribute('aria-invalid', 'true');
+            errorDiv.textContent = errorMessage;
+        } else {
+            input.classList.remove('invalid');
+            input.removeAttribute('aria-invalid');
+            errorDiv.textContent = '';
+        }
+        return !errorMessage;
+    };
+
+    // Real-time validation
+    fullNameInput.addEventListener('blur', () => validateField(fullNameInput, validators.fullName));
+    emailInput.addEventListener('blur', () => validateField(emailInput, validators.email));
+    phoneInput.addEventListener('blur', () => validateField(phoneInput, validators.phone));
+
+    form.addEventListener('submit', (e) => {
+        e.preventDefault();
+        
+        const isNameValid = validateField(fullNameInput, validators.fullName);
+        const isEmailValid = validateField(emailInput, validators.email);
+        const isPhoneValid = validateField(phoneInput, validators.phone);
+
+        if (isNameValid && isEmailValid && isPhoneValid) {
+            alert('Form submitted successfully!');
+            form.reset();
+            // Clear any lingering invalid states
+            [fullNameInput, emailInput, phoneInput].forEach(input => {
+                input.classList.remove('invalid');
+                input.removeAttribute('aria-invalid');
+                document.getElementById(`${input.id}Error`).textContent = '';
+            });
+        }
+    });
+});
+
